/**
 * Interview prep (/account/interview): 100 questions asked most often in
 * internship, campus-placement, first-job, college-admission and scholarship
 * interviews in India - 10 per area - each with why it's asked, how to
 * answer, a model answer and the mistake to avoid. Model answers are
 * examples written for a final-year student or fresher: students should
 * swap in their own facts, never memorise them word for word.
 */

export type CatKey = "about" | "strengths" | "motivation" | "education" | "teamwork" | "leadership" | "problems" | "situational" | "admission" | "closing";

export const CATEGORIES: { key: CatKey; label: string; text: string }[] = [
  { key: "about", label: "About you", text: "The openers - who you are, in under two minutes." },
  { key: "strengths", label: "Strengths & weaknesses", text: "Self-awareness, with proof." },
  { key: "motivation", label: "Why this role & company", text: "Show you chose them, not just any job." },
  { key: "education", label: "Education & learning", text: "Your studies, projects and how you learn." },
  { key: "teamwork", label: "Teamwork & conflict", text: "How you work with - and disagree with - people." },
  { key: "leadership", label: "Leadership & initiative", text: "Times you took charge or went beyond the brief." },
  { key: "problems", label: "Problems, pressure & failure", text: "Behavioural questions - answer with STAR." },
  { key: "situational", label: "What would you do if…", text: "Hypotheticals that test judgement." },
  { key: "admission", label: "College & scholarship interviews", text: "For admissions, scholarships and fellowships." },
  { key: "closing", label: "HR, salary & closing", text: "Logistics, money and your questions for them." },
];

export interface InterviewQ {
  id: string;
  cat: CatKey;
  q: string;
  /** What the interviewer is really checking. */
  why: string;
  /** How to build a good answer. */
  how: string;
  /** A model answer - an example to adapt, not a script. */
  answer: string;
  /** The common mistake. */
  avoid: string;
}

const Q = (cat: CatKey, n: number, q: string, why: string, how: string, answer: string, avoid: string): InterviewQ => ({ id: `${cat}-${n}`, cat, q, why, how, answer, avoid });

